// Runtime configuration. The lobby server is hard-coded (we support exactly one);
// only the bot account, naming, and the control token come from bindings/secrets.

/**
 * The single supported lobby server: Beyond All Reason production Teiserver.
 * We speak the Spring protocol in plaintext on this port (no TLS).
 */
export const LOBBY_SERVER = {
  host: "server4.beyondallreason.info",
  port: 8200,
  /** Metadata from the BAR client server list (informational). */
  name: "BAR",
  game: "byar",
} as const;

// The Worker `Env` shape is generated by `cf workers types` (.cloudflare/types)
// from cloudflare.config.ts — that global interface already declares the vars
// (ACCESS_*, BOT_*, SRC_MODES, …) and the Durable Object bindings. Secrets and
// optional vars are NOT in cloudflare.config.ts, so they aren't generated;
// declare them here by merging into the generated global `Env`.
declare global {
  interface Env {
    /** base64(md5(password)) — pre-hashed. Secret. */
    BOT_PASSWORD_HASH: string;
    /**
     * The bot account's PLAINTEXT password. Secret. Handed to the container-hosted
     * bot (src/bot/bot.ts hashes it itself for the lobby LOGIN and uses it as-is
     * for the Teiserver web login).
     */
    BOT_PASSWORD?: string;
    /** LOS lookup base URL override for the container-hosted bot (optional var). */
    BOT_LAVAOS_URL?: string;
    /** bearer token gating the HTTP control plane. Secret (optional). */
    CONTROL_TOKEN?: string;
    /**
     * "true" turns on the /login page's dev section: log in as any rated
     * player without the bot. Local development only — set it in .dev.vars,
     * never in cloudflare.config.ts or as a deployed secret.
     */
    DEV_LOGIN?: string;
    /**
     * The Access SERVICE TOKEN the container bot sends on /api/bot/* calls
     * (CF-Access-Client-Id / CF-Access-Client-Secret). Secrets; handed to the
     * container by BotContainer.
     */
    ACCESS_BOT_CLIENT_ID?: string;
    ACCESS_BOT_CLIENT_SECRET?: string;
    /**
     * "true" makes every request an admin (no Access cookie can exist on
     * localhost). Local development only — .dev.vars, never cloudflare.config.ts.
     */
    ADMIN_OPEN?: string;
    /** Singleton DO holding a logged-in Teiserver web session (src=teiserver). */
    TEISERVER: DurableObjectNamespace<import("./teiserverDO").TeiserverDO>;
    /** Plaintext password for the Teiserver web login (src=teiserver). Secret. */
    TEISERVER_PASSWORD?: string;
    /** Teiserver web-login email (secret), shared by the Worker scraper and the bot. */
    TEISERVER_EMAIL?: string;
    /** override for the lobby compatibility flags (optional var). */
    COMPAT_FLAGS?: string;
    /**
     * Debug flag (optional var). When set to "true", the TeiserverDO logs every
     * web request/response it makes to Teiserver — except the login, whose POST
     * body carries the account password. Off (unset) in production.
     */
    DEBUG?: string;
  }
}

// ---------------------------------------------------------------------------
// `src` modes for GET /api/lobbies[/:id]
// ---------------------------------------------------------------------------

/**
 * Every lobby `src` mode the Worker knows how to serve. The `SRC_MODES` var
 * (see below) enables a subset of these; a request for a known-but-disabled
 * mode is rejected with a 400, same as a wholly unknown mode.
 */
export const KNOWN_SRC_MODES = ["teiserver", "proxy", "rtsapi"] as const;
export type SrcMode = (typeof KNOWN_SRC_MODES)[number];

export interface SrcModes {
  /** The enabled modes, in declared order. */
  modes: SrcMode[];
  /** The default mode (the first enabled), used when `?src=` is omitted. */
  defaultMode: SrcMode;
}

/**
 * Resolve the enabled `src` modes from the `SRC_MODES` var: a comma-separated
 * list of mode names (e.g. `"teiserver,proxy,rtsapi"`). The **first** entry is
 * the default used when `?src=` is omitted; any mode not listed is disabled and
 * its requests get a 400. Whitespace around names is trimmed and unknown names
 * (typos, or modes the Worker can't serve) are dropped. If the var is unset,
 * empty, or lists no known mode, all known modes are enabled (default order).
 */
export function enabledSrcModes(env: Env): SrcModes {
  const known = new Set<string>(KNOWN_SRC_MODES);
  const requested = (env.SRC_MODES ?? "")
    .split(",")
    .map((s) => s.trim())
    .filter((s): s is SrcMode => known.has(s));
  // De-dupe while preserving order, so the first listed mode stays the default.
  const modes = [...new Set(requested)];
  const list = modes.length > 0 ? modes : [...KNOWN_SRC_MODES];
  return { modes: list, defaultMode: list[0] };
}

export interface BotConfig {
  server: typeof LOBBY_SERVER;
  /** Default account used when a room is started without explicit credentials. */
  defaultUsername: string;
  defaultPasswordHash: string;
  lobbyName: string;
  compatFlags: string;
  controlToken?: string;
}

/**
 * Persisted runtime configuration, settable at runtime via `POST /admin/config`
 * and stored in the Dispatcher's Durable Object storage. Distinct from `BotConfig`,
 * which is derived from environment bindings/secrets.
 */
export interface LavabalanceConfig {
  /** Battle (lobby) ids the bot should treat as managed "lava" lobbies. */
  lava_lobbies: number[];
}

/** Config used before anything has been set via `POST /admin/config`. */
export const DEFAULT_CONFIG: LavabalanceConfig = { lava_lobbies: [] };

/**
 * Validate and normalize an untrusted config payload (e.g. a request body).
 * Throws an `Error` with a human-readable message on bad shape.
 */
export function parseConfig(input: unknown): LavabalanceConfig {
  if (typeof input !== "object" || input === null || Array.isArray(input)) {
    throw new Error("config must be a JSON object");
  }
  const lobbies = (input as Record<string, unknown>).lava_lobbies;
  if (
    !Array.isArray(lobbies) ||
    !lobbies.every((n) => typeof n === "number" && Number.isFinite(n))
  ) {
    throw new Error("lava_lobbies must be an array of numbers");
  }
  return { lava_lobbies: lobbies as number[] };
}

export function buildConfig(env: Env): BotConfig {
  return {
    server: LOBBY_SERVER,
    defaultUsername: env.BOT_USERNAME,
    defaultPasswordHash: env.BOT_PASSWORD_HASH,
    // This becomes the user's `lobby_client` name that Teiserver broadcasts in
    // ADDUSER. Keep it as a plain, identifiable client name.
    lobbyName: env.BOT_LOBBY_NAME ?? "lavabalance",
    // Matches BYAR-Chobby; Teiserver requires these for a normal session.
    compatFlags: env.COMPAT_FLAGS ?? "b sp",
    controlToken: env.CONTROL_TOKEN,
  };
}
